import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Security Practices","description":"","frontmatter":{},"headers":[],"relativePath":"security/practices.md","filePath":"security/practices.md"}'),r={name:"security/practices.md"};function n(s,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="security-practices" tabindex="-1">Security Practices <a class="header-anchor" href="#security-practices" aria-label="Permalink to &quot;Security Practices&quot;">​</a></h1><p>This page is an operator checklist for the current implementation. It avoids fixed security ratings and source line numbers, which become stale as the code changes.</p><h3 id="installation-secrets" tabindex="-1">Installation Secrets <a class="header-anchor" href="#installation-secrets" aria-label="Permalink to &quot;Installation Secrets&quot;">​</a></h3><p>Protect these values and files:</p><ul><li><code>APP_KEY</code>, <code>API_KEY_PEPPER</code>, and <code>FERNET_SALT</code> in <code>.env</code>;</li><li>broker API credentials and callback configuration in <code>.env</code>;</li><li><code>db/tradeboard.db</code>, <code>db/logs.db</code>, <code>db/latency.db</code>, <code>db/health.db</code>, <code>db/sandbox.db</code>, and <code>db/historify.duckdb</code>;</li><li>Remote MCP signing keys;</li><li>strategy environment variables, source files, and backups.</li></ul><p>Official first-run and install paths replace sample placeholders with random values. Never restore placeholder secrets over an existing deployment. Do not rotate the pepper or Fernet material without following a migration procedure that accounts for hashes and ciphertext.</p><h3 id="account-authentication" tabindex="-1">Account Authentication <a class="header-anchor" href="#account-authentication" aria-label="Permalink to &quot;Account Authentication&quot;">​</a></h3><ul><li>Use a unique application password and enable login TOTP.</li><li>The current TOTP implementation does not generate recovery codes. Preserve the setup secret securely before replacing an authenticator device.</li><li>Review active sessions from the Security dashboard and change the password to revoke device sessions after suspected compromise.</li><li>Treat broker TOTP/PIN flows as separate credentials from Tradeboard TOTP.</li></ul><h3 id="rest-api-keys" tabindex="-1">REST API Keys <a class="header-anchor" href="#rest-api-keys" aria-label="Permalink to &quot;REST API Keys&quot;">​</a></h3><ul><li>Tradeboard generates one current 64-character hexadecimal API key per user.</li><li>Store it in a secret manager or environment variable, not in strategy source.</li><li>Regeneration invalidates the old key immediately; update every client together.</li><li>Most <code>/api/v1</code> schemas require <code>apikey</code> in the JSON body. Do not assume generic Bearer or header authentication.</li><li>The current key has no per-operation scopes. Possession authorizes the public REST surface subject to validation, mode, Action Center behavior, and rate limits.</li><li>Test order workflows in Analyzer Mode before using the same key with live mode.</li></ul><h3 id="public-deployment" tabindex="-1">Public Deployment <a class="header-anchor" href="#public-deployment" aria-label="Permalink to &quot;Public Deployment&quot;">​</a></h3><ul><li>Terminate TLS at a maintained reverse proxy.</li><li>Restrict direct access to Flask, port 8765 WebSocket, and port 5555 ZeroMQ.</li><li>Keep <code>ZMQ_HOST</code> on loopback unless a deliberately protected multi-host topology is required.</li><li>Configure the host firewall or cloud security group; Tradeboard has no CIDR allowlist.</li><li>Set <code>TRUST_PROXY_HEADERS=True</code> only when the reverse proxy is the sole path to the app.</li><li>Keep debug mode disabled on any non-loopback deployment.</li><li>Review CORS and CSP settings after adding an external frontend or integration.</li></ul><h3 id="rate-limits-and-ip-bans" tabindex="-1">Rate Limits and IP Bans <a class="header-anchor" href="#rate-limits-and-ip-bans" aria-label="Permalink to &quot;Rate Limits and IP Bans&quot;">​</a></h3><p>Endpoint limits come from the deployment environment. <code>.sample.env</code> defaults include separate login, reset, general API, order, smart-order, webhook, strategy, and MCP limits.</p><p>Automatic IP banning is off by default. Before enabling it:</p><ol><li>verify the proxy/IP boundary;</li><li>review legitimate 404 and invalid-key traffic;</li><li>choose temporary or permanent durations deliberately;</li><li>retain host-console access for recovery;</li><li>test manual unban and tracker clearing.</li></ol><p>Rate limits and IP bans are complementary; neither replaces upstream denial-of-service controls.</p><h3 id="traffic-and-logs" tabindex="-1">Traffic and Logs <a class="header-anchor" href="#traffic-and-logs" aria-label="Permalink to &quot;Traffic and Logs&quot;">​</a></h3><p>Traffic logging captures metadata only. It excludes request/response bodies and headers, so it should not contain body-carried API keys. Other application logs can still contain broker error strings or operator-provided data; review logs before sharing them.</p><p>Set retention values according to operational and privacy needs, preserve evidence before cleanup, and keep <code>logs.db</code> access restricted. Traffic retention defaults to <code>TRAFFIC_LOG_RETENTION_DAYS=30</code> in <code>.sample.env</code>.</p><h3 id="remote-mcp" tabindex="-1">Remote MCP <a class="header-anchor" href="#remote-mcp" aria-label="Permalink to &quot;Remote MCP&quot;">​</a></h3><ul><li>Leave <code>MCP_HTTP_ENABLED</code> off unless hosted clients are required.</li><li>Keep client approval on and <code>MCP_OAUTH_WRITE_SCOPE_ENABLED</code> off initially.</li><li>Enable MCP TOTP before granting <code>write:orders</code>.</li><li>Verify requested redirect URI and scopes on every approval.</li><li>Use the kill switch after suspected token exposure; refresh-token reuse revokes the entire token family.</li><li>Keep MCP signing keys and audit logs in the backup and incident-response plan.</li></ul><h3 id="updates-and-backups" tabindex="-1">Updates and Backups <a class="header-anchor" href="#updates-and-backups" aria-label="Permalink to &quot;Updates and Backups&quot;">​</a></h3><p>Use <code>bash install/update.sh</code> for the supported native update path. Back up all six stores, <code>.env</code>, signing keys, and strategy files before upgrading. The current updater omits <code>health.db</code> from its automatic database loop, so copy it separately when retaining health history matters.</p><p>After an update:</p><ol><li>review migration output and service logs;</li><li>verify <code>/auth/app-info</code>;</li><li>sign in and reconnect the broker;</li><li>test a read-only REST call and WebSocket authentication;</li><li>test Analyzer Mode before live order execution.</li></ol><h3 id="incident-response" tabindex="-1">Incident Response <a class="header-anchor" href="#incident-response" aria-label="Permalink to &quot;Incident Response&quot;">​</a></h3><p>When credentials or the host may be compromised:</p><ol><li>stop automated strategies and retain broker-terminal access;</li><li>isolate public access at the proxy or firewall;</li><li>regenerate the Tradeboard API key;</li><li>revoke application sessions and MCP tokens;</li><li>revoke or rotate broker credentials through the broker;</li><li>preserve and inspect application, proxy, OS, and broker logs;</li><li>rebuild or restore from a known-good revision and matching backups when host integrity is uncertain.</li></ol>',29)])])}const b=a(r,[["render",n]]);export{u as __pageData,b as default};
